from dataclasses import dataclass
from typing import Dict, Iterable, Tuple

@dataclass(frozen=True)
class Transfer:
    id: str
    source: str
    target: str
    cents: int

@dataclass
class Snapshot:
    balances: Dict[str, int]
    applied: Dict[str, Tuple[str, str, int]]

def replay(initial: Snapshot, events: Iterable[Transfer]) -> Snapshot:
    balances = dict(initial.balances)
    applied = dict(initial.applied)
    if any(type(v) is not int or v < 0 for v in balances.values()):
        raise ValueError("invalid initial balance")
    for event in events:
        if not event.id or type(event.cents) is not int or event.cents <= 0:
            raise ValueError("invalid transfer")
        if event.source == event.target:
            raise ValueError("same account")
        fingerprint = (event.source, event.target, event.cents)
        if event.id in applied:
            if applied[event.id] != fingerprint:
                raise ValueError("idempotency conflict")
            continue
        if event.source not in balances or event.target not in balances:
            raise ValueError("unknown account")
        if balances[event.source] < event.cents:
            raise ValueError("insufficient funds")
        balances[event.source] -= event.cents
        balances[event.target] += event.cents
        applied[event.id] = fingerprint
    return Snapshot(balances, applied)

