import unittest

class LedgerTests(unittest.TestCase):
    def setUp(self):
        self.initial = Snapshot({"A": 1000, "B": 100}, {})

    def test_duplicate_and_conservation(self):
        event = Transfer("t1", "A", "B", 300)
        result = replay(self.initial, [event, event])
        self.assertEqual(result.balances, {"A": 700, "B": 400})
        self.assertEqual(sum(result.balances.values()), 1100)
        self.assertEqual(replay(result, [event]), result)
        self.assertEqual(self.initial.balances["A"], 1000)

    def test_conflict(self):
        with self.assertRaisesRegex(ValueError, "conflict"):
            replay(self.initial, [Transfer("x", "A", "B", 10),
                                  Transfer("x", "A", "B", 20)])

    def test_failure_preserves_input(self):
        with self.assertRaisesRegex(ValueError, "insufficient"):
            replay(self.initial, [Transfer("x", "A", "B", 2000)])
        self.assertEqual(self.initial, Snapshot({"A": 1000, "B": 100}, {}))

    def test_invalid_and_empty(self):
        self.assertEqual(replay(self.initial, []), self.initial)
        for cents in (0, -1, True):
            with self.assertRaises(ValueError):
                replay(self.initial, [Transfer("x", "A", "B", cents)])

if __name__ == "__main__":
    unittest.main()

