from collections import defaultdict, deque
from typing import Deque, Dict, Optional

class SlidingWindow:
    def __init__(self, limit: int, window_ms: int):
        if type(limit) is not int or type(window_ms) is not int or limit <= 0 or window_ms <= 0:
            raise ValueError("positive integer limit and window required")
        self.limit = limit
        self.window_ms = window_ms
        self.events: Dict[str, Deque[int]] = defaultdict(deque)
        self.last_now: Optional[int] = None

    def allow(self, key: str, now_ms: int) -> bool:
        if type(now_ms) is not int:
            raise ValueError("integer timestamp required")
        if self.last_now is not None and now_ms < self.last_now:
            raise ValueError("time moved backwards")
        self.last_now = now_ms
        queue = self.events[key]
        while queue and queue[0] <= now_ms - self.window_ms:
            queue.popleft()
        if len(queue) >= self.limit:
            return False
        queue.append(now_ms)
        return True

from heapq import heappop, heappush, heapify
from typing import Dict, List

def deployment_order(dependencies: Dict[str, List[str]]) -> List[str]:
    nodes = set(dependencies)
    for values in dependencies.values():
        nodes.update(values)
    outgoing = {node: set() for node in nodes}
    indegree = {node: 0 for node in nodes}
    for service, prerequisites in dependencies.items():
        for prerequisite in set(prerequisites):
            outgoing[prerequisite].add(service)
            indegree[service] += 1
    ready = [node for node in nodes if indegree[node] == 0]
    heapify(ready)
    result = []
    while ready:
        node = heappop(ready)
        result.append(node)
        for following in outgoing[node]:
            indegree[following] -= 1
            if indegree[following] == 0:
                heappush(ready, following)
    if len(result) != len(nodes):
        raise ValueError("dependency cycle")
    return result

