import unittest

class DagTests(unittest.TestCase):
    def test_order(self):
        deps = {"api": ["db", "cache", "db"], "worker": ["db"], "db": []}
        result = deployment_order(deps)
        self.assertEqual(result, ["cache", "db", "api", "worker"])
        position = {node: i for i, node in enumerate(result)}
        for node, before in deps.items():
            for prerequisite in before:
                self.assertLess(position[prerequisite], position[node])

    def test_cycles_and_empty(self):
        self.assertEqual(deployment_order({}), [])
        for graph in ({"a": ["a"]}, {"a": ["b"], "b": ["a"]}):
            with self.assertRaises(ValueError):
                deployment_order(graph)

if __name__ == "__main__":
    unittest.main()

