CREATE TEMP VIEW statement AS
SELECT id, account_id, occurred_at, cents,
       sum(cents) OVER (
         PARTITION BY account_id ORDER BY occurred_at,id
         ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS balance
FROM entries;

